mapper.select:
select r.review_id,r.order_id,r.service_id,s.service_name,r.user_id,r.user_info,r.rating,r.content,r.reply_content,r.reply_status,r.status,r.create_time
from zjudg_service_review r
left join zjudg_service s on s.service_id=r.service_id

  and r.service_id=#{serviceId}
  and s.service_name like concat('%',#{serviceName},'%')
  and r.user_info like concat('%',#{userInfo},'%')
  and r.reply_status=#{replyStatus}
  and r.rating=#{rating}
  and r.create_time >= #{params.beginTime}
  and r.create_time < date_add(#{params.endTime},interval 1 day)

order by r.create_time desc
